<?php if(!empty($maintenance)): ?><section class="lc-card"><p class="eyebrow">Tindak lanjut temuan</p><h2>Riwayat perbaikan fasilitas</h2><p class="muted">Status pekerjaan melengkapi pemeriksaan fasilitas. Kondisi barang sesudah perbaikan tetap dicatat melalui pemeriksaan berikutnya.</p><div class="lc-table-wrap"><table><thead><tr><th>Dilaporkan</th><th>Temuan</th><th>Status pekerjaan</th><th>Selesai</th><th>Catatan</th></tr></thead><tbody><?php foreach($maintenance as $ticket): ?><tr><td><?= gh_lc_e(gh_lc_v($ticket,'reported_at')); ?></td><td><strong><?= gh_lc_e(gh_lc_v($ticket,'issue_title')); ?></strong><br><small><?= gh_lc_e(gh_lc_v($ticket,'ticket_no')); ?></small></td><td><span class="lc-pill <?= gh_lc_v($ticket,'status')==='done'?'':'warn'; ?>"><?= gh_lc_e(gh_lc_label(gh_lc_v($ticket,'status'))); ?></span></td><td><?= gh_lc_e(gh_lc_v($ticket,'finished_at')); ?></td><td><?= gh_lc_e(gh_lc_v($ticket,'notes','')); ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
